"""End-to-end tests for the autogenerated exemption predicate.

Verifies that commits with the ``Autogenerated: true`` trailer are correctly
exempted from changelog coverage in three contexts:

1. Basic exemption through ``filter_exempt_commits()`` and ``check_coverage()``.
2. Cross-release boundary: autogenerated commits from one release cycle
   landing in the next release's unreleased range.
3. Multi-releasable monorepo: autogenerated exemption applies regardless
   of which releasable's context is being checked.
"""

import json

import pytest

from conftest import run_git as _run_git, git_head as _git_head, make_commit as _make_commit
from rlsbl.changelog.exemptions import (
    create_default_registry,
    is_autogenerated,
)
from rlsbl.changelog.schema import ChangelogEntry
from rlsbl.changelog.validate import (
    check_coverage,
    filter_exempt_commits,
)


@pytest.fixture
def git_repo(tmp_path, monkeypatch):
    """Create a git repo with an initial commit, a v0.0.0 tag, and .rlsbl/changes/."""
    repo = tmp_path / "repo"
    repo.mkdir()
    monkeypatch.chdir(repo)
    _run_git(repo, "init", "-q")
    _run_git(repo, "config", "user.email", "test@test.local")
    _run_git(repo, "config", "user.name", "Test")
    (repo / "README.md").write_text("# test\n")
    _run_git(repo, "add", "README.md")
    _run_git(repo, "commit", "-q", "-m", "initial")
    _run_git(repo, "tag", "v0.0.0")
    changes = repo / ".rlsbl" / "changes"
    changes.mkdir(parents=True)
    return repo


def _make_autogenerated_commit(repo, filename="generated.txt", content=None):
    """Create a commit with the Autogenerated: true trailer. Returns its SHA."""
    filepath = repo / filename
    filepath.write_text(content or f"generated content\n")
    _run_git(repo, "add", filename)
    _run_git(repo, "commit", "-m", f"auto: update {filename}\n\nAutogenerated: true")
    return _git_head(repo)


# ---------------------------------------------------------------------------
# 1. Basic exemption
# ---------------------------------------------------------------------------


class TestBasicAutogeneratedExemption:
    """Autogenerated commits are exempted from coverage by filter_exempt_commits
    and by check_coverage end-to-end."""

    def test_filter_exempt_commits_removes_autogenerated(self, git_repo):
        """filter_exempt_commits removes the autogenerated commit and increments
        the autogenerated stat."""
        sha = _make_autogenerated_commit(git_repo)

        remaining, stats = filter_exempt_commits([sha])
        assert remaining == []
        assert stats.autogenerated == 1
        assert stats.changelog_only == 0

    def test_check_coverage_passes_with_only_autogenerated_commit(self, git_repo):
        """check_coverage passes when the only unreleased commit is autogenerated,
        even with no JSONL entries at all."""
        sha = _make_autogenerated_commit(git_repo)

        # No entries -- the autogenerated commit should be exempted
        entries = []
        passed, details = check_coverage(entries)
        assert passed is True
        assert any("autogenerated" in d for d in details)

    def test_check_coverage_passes_with_mixed_commits(self, git_repo):
        """check_coverage passes when autogenerated commits coexist with
        covered normal commits."""
        sha_auto = _make_autogenerated_commit(git_repo)
        sha_normal = _make_commit(git_repo, "code.py", "real change")

        # Cover only the normal commit
        entries = [ChangelogEntry(commits=[sha_normal], user_facing=False)]
        passed, details = check_coverage(entries)
        assert passed is True
        assert any("autogenerated" in d for d in details)

    def test_check_coverage_fails_when_normal_commit_uncovered(self, git_repo):
        """check_coverage fails when a normal commit is uncovered, even if
        autogenerated commits are present and exempted."""
        sha_auto = _make_autogenerated_commit(git_repo)
        sha_normal = _make_commit(git_repo, "code.py", "real change")

        # No entries -- autogenerated is exempt but normal is not
        entries = []
        passed, details = check_coverage(entries)
        assert passed is False
        assert any("not covered" in d for d in details)

    def test_is_autogenerated_predicate_registered_in_default_registry(self, git_repo):
        """The default registry includes is_autogenerated as the first rule."""
        sha = _make_autogenerated_commit(git_repo)

        registry = create_default_registry()
        exempt, reason = registry.check(sha)
        assert exempt is True
        assert "Autogenerated" in reason

    def test_is_autogenerated_predicate_reads_trailer(self, git_repo):
        """is_autogenerated returns True only when the trailer is present."""
        sha_auto = _make_autogenerated_commit(git_repo)
        sha_normal = _make_commit(git_repo, "normal.py", "no trailer")

        assert is_autogenerated(sha_auto) is True
        assert is_autogenerated(sha_normal) is False


# ---------------------------------------------------------------------------
# 2. Cross-release boundary
# ---------------------------------------------------------------------------


class TestCrossReleaseBoundary:
    """An autogenerated commit from a previous release cycle that lands in
    the next release's unreleased range is still exempted.

    This simulates the Phase 1c scenario: selfdoc generates a commit during
    release N, but it ends up in the unreleased range for release N+1.
    """

    def test_autogenerated_commit_exempted_across_release_boundary(self, git_repo):
        """After tagging release N, an autogenerated commit created before
        the tag (but after the *previous* tag) would have been exempted.
        More importantly, an autogenerated commit *after* the new tag is
        also exempted in the next release cycle's coverage check."""
        repo = git_repo

        # --- Release cycle 1: create a normal commit and release ---
        sha_r1 = _make_commit(repo, "feature.py", "feature for v0.1.0")

        # Cover it in JSONL so the release would be valid
        unreleased = repo / ".rlsbl" / "changes" / "unreleased.jsonl"
        unreleased.write_text(
            json.dumps({"commits": [sha_r1], "user_facing": True,
                        "description": "feature", "type": "feature"}) + "\n"
        )
        _run_git(repo, "add", ".rlsbl/changes/unreleased.jsonl")
        _run_git(repo, "commit", "-q", "-m", "add changelog entry for v0.1.0")

        # Tag v0.1.0
        _run_git(repo, "tag", "v0.1.0")

        # --- Between releases: autogenerated commit lands ---
        # This simulates a selfdoc commit or similar that was created
        # as part of release N's pipeline but lands after the tag.
        sha_auto = _make_autogenerated_commit(repo, "api_gen.md", "auto docs")

        # --- Release cycle 2: a normal commit ---
        sha_r2 = _make_commit(repo, "bugfix.py", "bugfix for v0.1.1")

        # Check coverage for release cycle 2 (v0.1.0..HEAD)
        # The autogenerated commit should be exempted, only sha_r2 needs coverage
        entries = [ChangelogEntry(commits=[sha_r2], user_facing=False)]
        passed, details = check_coverage(entries)
        assert passed is True
        assert any("autogenerated" in d for d in details)

    def test_autogenerated_commit_not_double_counted_across_boundary(self, git_repo):
        """An autogenerated commit in the unreleased range does not appear
        as uncovered -- it is fully exempted, not just ignored."""
        repo = git_repo

        # Tag a release
        sha_r1 = _make_commit(repo, "v1.py", "release 1")
        _run_git(repo, "tag", "v0.1.0")

        # Autogenerated commit in the new cycle
        sha_auto = _make_autogenerated_commit(repo)

        # No other commits, no entries -- should pass because the only
        # unreleased commit is autogenerated
        entries = []
        passed, details = check_coverage(entries)
        assert passed is True
        assert any("autogenerated" in d for d in details)

    def test_multiple_autogenerated_commits_all_exempted(self, git_repo):
        """Multiple autogenerated commits in the unreleased range are all
        exempted, with the correct count in details."""
        repo = git_repo

        sha_r1 = _make_commit(repo, "v1.py", "release 1")
        _run_git(repo, "tag", "v0.1.0")

        # Three autogenerated commits in the new cycle
        _make_autogenerated_commit(repo, "gen1.txt", "gen 1")
        _make_autogenerated_commit(repo, "gen2.txt", "gen 2")
        _make_autogenerated_commit(repo, "gen3.txt", "gen 3")

        entries = []
        passed, details = check_coverage(entries)
        assert passed is True
        # Should report 3 autogenerated commits skipped
        auto_details = [d for d in details if "autogenerated" in d]
        assert len(auto_details) == 1
        assert "3" in auto_details[0]


# ---------------------------------------------------------------------------
# 3. Multi-releasable monorepo context
# ---------------------------------------------------------------------------


class TestMultiReleasableMonorepo:
    """In a monorepo with 2+ releasables, the autogenerated exemption works
    regardless of which releasable's context is being checked."""

    @pytest.fixture
    def monorepo(self, tmp_path, monkeypatch):
        """Create a monorepo with two packages (pkg-a, pkg-b), each with
        its own tag and .rlsbl/changes/ directory."""
        repo = tmp_path / "repo"
        repo.mkdir()
        monkeypatch.chdir(repo)

        _run_git(repo, "init", "-q")
        _run_git(repo, "config", "user.email", "test@test.local")
        _run_git(repo, "config", "user.name", "Test")

        # Create package directories
        (repo / "pkg-a").mkdir()
        (repo / "pkg-a" / "lib.py").write_text("a = 1\n")
        (repo / "pkg-a" / ".rlsbl" / "changes").mkdir(parents=True)

        (repo / "pkg-b").mkdir()
        (repo / "pkg-b" / "lib.py").write_text("b = 1\n")
        (repo / "pkg-b" / ".rlsbl" / "changes").mkdir(parents=True)

        (repo / "README.md").write_text("# monorepo\n")
        _run_git(repo, "add", ".")
        _run_git(repo, "commit", "-q", "-m", "initial monorepo setup")

        # Tag baselines
        _run_git(repo, "tag", "pkg-a@v0.1.0")
        _run_git(repo, "tag", "pkg-b@v0.1.0")

        return repo

    def _project_a(self):
        return {"path": "pkg-a", "name": "pkg-a"}

    def _project_b(self):
        return {"path": "pkg-b", "name": "pkg-b"}

    def test_autogenerated_commit_exempted_for_project_a(self, monorepo):
        """An autogenerated commit touching pkg-a files is exempted when
        checking coverage for pkg-a."""
        repo = monorepo

        # Autogenerated commit touching pkg-a
        (repo / "pkg-a" / "generated.py").write_text("# auto\n")
        _run_git(repo, "add", "pkg-a/generated.py")
        _run_git(repo, "commit", "-m", "auto: generate for pkg-a\n\nAutogenerated: true")

        entries = []
        passed, details = check_coverage(
            entries, tag_glob="pkg-a@v*", project=self._project_a()
        )
        assert passed is True
        assert any("autogenerated" in d for d in details)

    def test_autogenerated_commit_exempted_for_project_b(self, monorepo):
        """An autogenerated commit touching pkg-b files is exempted when
        checking coverage for pkg-b."""
        repo = monorepo

        # Autogenerated commit touching pkg-b
        (repo / "pkg-b" / "generated.py").write_text("# auto\n")
        _run_git(repo, "add", "pkg-b/generated.py")
        _run_git(repo, "commit", "-m", "auto: generate for pkg-b\n\nAutogenerated: true")

        entries = []
        passed, details = check_coverage(
            entries, tag_glob="pkg-b@v*", project=self._project_b()
        )
        assert passed is True
        assert any("autogenerated" in d for d in details)

    def test_autogenerated_commit_touching_both_packages(self, monorepo):
        """An autogenerated commit touching files in BOTH packages is
        exempted from coverage for both package A and package B."""
        repo = monorepo

        # Autogenerated commit touching both packages
        (repo / "pkg-a" / "shared_gen.py").write_text("# generated a\n")
        (repo / "pkg-b" / "shared_gen.py").write_text("# generated b\n")
        _run_git(repo, "add", "pkg-a/shared_gen.py")
        _run_git(repo, "add", "pkg-b/shared_gen.py")
        _run_git(repo, "commit", "-m", "auto: generate shared\n\nAutogenerated: true")

        # Check pkg-a: should be exempted
        entries_a = []
        passed_a, details_a = check_coverage(
            entries_a, tag_glob="pkg-a@v*", project=self._project_a()
        )
        assert passed_a is True
        assert any("autogenerated" in d for d in details_a)

        # Check pkg-b: should also be exempted
        entries_b = []
        passed_b, details_b = check_coverage(
            entries_b, tag_glob="pkg-b@v*", project=self._project_b()
        )
        assert passed_b is True
        assert any("autogenerated" in d for d in details_b)

    def test_autogenerated_exemption_does_not_hide_uncovered_normal_commits(self, monorepo):
        """In monorepo mode, autogenerated exemption does not mask uncovered
        normal commits in the same package."""
        repo = monorepo

        # Autogenerated commit touching pkg-a
        (repo / "pkg-a" / "generated.py").write_text("# auto\n")
        _run_git(repo, "add", "pkg-a/generated.py")
        _run_git(repo, "commit", "-m", "auto: gen\n\nAutogenerated: true")

        # Normal commit touching pkg-a (uncovered)
        (repo / "pkg-a" / "lib.py").write_text("a = 2\n")
        _run_git(repo, "add", "pkg-a/lib.py")
        _run_git(repo, "commit", "-q", "-m", "real change to pkg-a")

        entries = []
        passed, details = check_coverage(
            entries, tag_glob="pkg-a@v*", project=self._project_a()
        )
        assert passed is False
        assert any("not covered" in d for d in details)
        # Autogenerated commit should still be reported as skipped
        assert any("autogenerated" in d for d in details)

    def test_autogenerated_commit_outside_package_not_counted(self, monorepo):
        """An autogenerated commit touching only root-level files is filtered
        out by the project scope filter -- it never reaches the exemption
        check for pkg-a or pkg-b."""
        repo = monorepo

        # Autogenerated commit touching only root files
        (repo / "root_gen.txt").write_text("generated root\n")
        _run_git(repo, "add", "root_gen.txt")
        _run_git(repo, "commit", "-m", "auto: root gen\n\nAutogenerated: true")

        # For pkg-a: the commit is outside pkg-a's scope entirely
        entries = []
        passed, details = check_coverage(
            entries, tag_glob="pkg-a@v*", project=self._project_a()
        )
        assert passed is True
        # Should report it as outside package directory, not as autogenerated
        assert any("outside package directory" in d for d in details)

    def test_autogenerated_exemption_with_releasable_member_list(self, monorepo):
        """When project is a list of member dicts (releasable mode), the
        autogenerated exemption still applies."""
        repo = monorepo

        # Autogenerated commit touching pkg-a
        (repo / "pkg-a" / "generated.py").write_text("# auto releasable\n")
        _run_git(repo, "add", "pkg-a/generated.py")
        _run_git(repo, "commit", "-m", "auto: releasable gen\n\nAutogenerated: true")

        # Pass project as a list (releasable members mode)
        members = [self._project_a()]
        entries = []
        passed, details = check_coverage(
            entries, tag_glob="pkg-a@v*", project=members
        )
        assert passed is True
        assert any("autogenerated" in d for d in details)
